189:     /**
190:      * Load new history.
191:      * @return {void}
192:      */
193:     function loadHistory() {
194:         var url = DATA_URL.concat("?offset=", nextOffset.toString());
195:         if (nextTime === null) {
196:             getJSON(url, receiveHistory);
197:         } else {
198:             url = url.concat("&start_time=", nextTime.toString());
199:             getJSON(url, receiveHistory);
200:         }
201:     }
202: 
203:     return loadHistory;
204: })();
